<?php
namespace App\Entity;
use Doctrine\Common\Collections\ArrayCollection; use Doctrine\Common\Collections\Collection; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity] #[ORM\Table(name:'engagement',uniqueConstraints:[new ORM\UniqueConstraint(name:'uniq_engagement_saison_pilote',columns:['saison_id','pilote_id'])])] class Engagement { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne(inversedBy:'engagements')] #[ORM\JoinColumn(nullable:false)] private ?Saison $saison=null; #[ORM\ManyToOne(inversedBy:'engagements')] #[ORM\JoinColumn(nullable:false)] private ?Pilote $pilote=null; #[ORM\ManyToOne(inversedBy:'engagements')] #[ORM\JoinColumn(nullable:false)] private ?Ecurie $ecurie=null; #[ORM\Column(nullable:true)] private ?int $numero=null; #[ORM\Column(length:30)] private string $statut='actif'; #[ORM\Column(type:'date',nullable:true)] private ?\DateTimeInterface $dateDebut=null; #[ORM\Column(type:'date',nullable:true)] private ?\DateTimeInterface $dateFin=null; #[ORM\OneToMany(mappedBy:'engagement',targetEntity:ResultatCourse::class)] private Collection $resultats; #[ORM\OneToMany(mappedBy:'engagement',targetEntity:TourPilote::class)] private Collection $tours; public function __construct(){$this->resultats=new ArrayCollection();$this->tours=new ArrayCollection();} public function getId():?int{return $this->id;} public function getSaison():?Saison{return $this->saison;} public function setSaison(?Saison $v):self{$this->saison=$v;return $this;} public function getPilote():?Pilote{return $this->pilote;} public function setPilote(?Pilote $v):self{$this->pilote=$v;return $this;} public function getEcurie():?Ecurie{return $this->ecurie;} public function setEcurie(?Ecurie $v):self{$this->ecurie=$v;return $this;} public function getNumero():?int{return $this->numero;} public function setNumero(?int $v):self{$this->numero=$v;return $this;} public function getStatut():string{return $this->statut;} public function setStatut(string $v):self{$this->statut=$v;return $this;} public function getDateDebut():?\DateTimeInterface{return $this->dateDebut;} public function setDateDebut(?\DateTimeInterface $v):self{$this->dateDebut=$v;return $this;} public function getDateFin():?\DateTimeInterface{return $this->dateFin;} public function setDateFin(?\DateTimeInterface $v):self{$this->dateFin=$v;return $this;} public function getResultats():Collection{return $this->resultats;} public function getTours():Collection{return $this->tours;} }
